import { afterEach, describe, expect, test } from "bun:test"
import { DevelopmentWorkspaceDatabase } from "@neuvetra/database"
import { createStagingServer, type StagingDatabase, type StagingLog } from "./server"
import { readStagingConfig, STAGING_PROFILE } from "./config"
import { serveStagingAsset, verifyStagingAssets } from "./assets"
import { mkdtemp, writeFile, mkdir, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import path from "node:path"

const REF = "abcdefghijklmnopqrst"
const OWNER = "11111111-1111-4111-8111-111111111111"
const ADMIN = "33333333-3333-4333-8333-333333333333"
const MEMBER = "44444444-4444-4444-8444-444444444444"
const OUTSIDER = "22222222-2222-4222-8222-222222222222"
const ORIGIN = "http://127.0.0.1:3015"
const environment = {
  NODE_ENV: "test", NEUVETRA_STAGING_ENABLED: "enabled", NEUVETRA_STAGING_PROFILE: STAGING_PROFILE,
  NEUVETRA_STAGING_PROJECT_REF: REF, NEUVETRA_STAGING_ORIGIN: ORIGIN,
  SUPABASE_URL: `https://${REF}.supabase.co`, SUPABASE_ANON_KEY: "sb_publishable_synthetic_fixture_not_a_real_key",
  DATABASE_URL: `postgres://neuvetra_runtime:synthetic-password@db.${REF}.supabase.co:5432/postgres`,
}
const input = { companyName: "Synthetic Acme, Inc.", facilityName: "Synthetic California office", countryCode: "US", stateCode: "CA", egridSubregion: "CAMX", reportingYear: 2023, approach: "operational_control" } as const
let cleanup: (() => Promise<void>) | undefined
afterEach(async () => { await cleanup?.(); cleanup = undefined })

async function fixture() {
  const db = await DevelopmentWorkspaceDatabase.create([OWNER, ADMIN, MEMBER, OUTSIDER])
  const workspace = await db.createWorkspaceWithSyntheticMembers(OWNER, input, [{ userId: ADMIN, role: "admin" }, { userId: MEMBER, role: "member" }])
  const invited = new Set([OWNER, ADMIN, MEMBER, OUTSIDER])
  const users: Record<string, string> = { "test-owner-session": OWNER, "test-admin-session": ADMIN, "test-member-session": MEMBER, "test-outsider-session": OUTSIDER }
  const logs: StagingLog[] = []
  let healthy = true
  let evidenceId: string | null = null
  const database = Object.assign(db, {
    async hasStagingAccess(userId: string) { return invited.has(userId) },
    async findStagingWorkspaceForUser(userId: string) {
      const allowed = invited.has(userId) ? await db.findWorkspace(userId, workspace.id) : null
      if (!allowed) return null
      return { workspace: allowed, role: userId === OWNER ? "owner" as const : userId === ADMIN ? "admin" as const : "member" as const, evidenceId }
    },
    async checkReadiness() { if (!healthy) throw new Error("sensitive-driver-value"); return { profile: STAGING_PROFILE, schemaVersion: 12 } },
  }) as StagingDatabase
  const app = await createStagingServer(readStagingConfig(environment), {
    database, validateUser: async (token) => token === "broken-session" ? Promise.reject(new Error("sensitive-auth-value")) : users[token] ? { id: users[token]!, phone: null, email: "private@example.invalid", fullName: "Private fixture" } : null,
    verifyAssets: async () => {}, serveAsset: async (name) => name === "/" ? new Response("Private staging sign-in") : null,
    log: (event) => logs.push(event),
  })
  cleanup = app.close
  const request = (pathname: string, token?: string, options: RequestInit = {}) => app.fetch(new Request(`${ORIGIN}${pathname}`, { ...options, headers: { origin: ORIGIN, ...(token ? { authorization: `Bearer ${token}` } : {}), ...options.headers } }))
  return { app, db, workspace, invited, logs, request, unhealthy: () => { healthy = false }, evidence: (id: string) => { evidenceId = id } }
}

describe("M63 private staging boundary", () => {
  test("configuration refuses demo mode, privileged key/login and mismatched targets without displaying secrets", () => {
    expect(readStagingConfig(environment).profile).toBe(STAGING_PROFILE)
    const serviceKey = `x.${Buffer.from(JSON.stringify({ role: "service_role", ref: REF })).toString("base64url")}.y`
    const bad = [
      { NODE_ENV: "development" }, { NEUVETRA_STAGING_ENABLED: "" }, { NEUVETRA_STAGING_PROFILE: "local_synthetic_development" },
      { SUPABASE_URL: "https://other.supabase.co" }, { SUPABASE_ANON_KEY: serviceKey }, { SUPABASE_ANON_KEY: "sb_secret_fixture" },
      { SUPABASE_ANON_KEY: "sb_publishable_" }, { NEUVETRA_STAGING_PROJECT_REF: "icockcoguyadhryzydvl", SUPABASE_URL: "https://icockcoguyadhryzydvl.supabase.co" },
      { DATABASE_URL: `postgres://postgres:sensitive@db.${REF}.supabase.co/postgres` },
      { DATABASE_URL: environment.DATABASE_URL + "?sslmode=disable" }, { NEUVETRA_STAGING_ORIGIN: "https://example.invalid/path" },
      { NEUVETRA_STAGING_DB_CA_PEM: "public-ca-fixture", NEUVETRA_STAGING_DB_CA_FILE: "/public-ca.crt" },
    ]
    for (const change of bad) expect(() => readStagingConfig({ ...environment, ...change })).toThrow("Private staging configuration is invalid.")
    const existing = { ...environment, NEUVETRA_STAGING_PROJECT_REF: "icockcoguyadhryzydvl", NEUVETRA_STAGING_REUSE_EXISTING: "confirmed", SUPABASE_URL: "https://icockcoguyadhryzydvl.supabase.co", DATABASE_URL: environment.DATABASE_URL.replace(REF, "icockcoguyadhryzydvl") }
    expect(readStagingConfig(existing).reuseExistingProject).toBe(true)
  })

  test("explicit existing-project reuse still requires verified database containment at startup", async () => {
    let closed = false
    const database = { checkReadiness: async () => ({ profile: STAGING_PROFILE, schemaVersion: 12 }), close: async () => { closed = true } } as unknown as StagingDatabase
    const config = readStagingConfig({ ...environment, NEUVETRA_STAGING_PROJECT_REF: "icockcoguyadhryzydvl", NEUVETRA_STAGING_REUSE_EXISTING: "confirmed", SUPABASE_URL: "https://icockcoguyadhryzydvl.supabase.co", DATABASE_URL: environment.DATABASE_URL.replace(REF, "icockcoguyadhryzydvl") })
    await expect(createStagingServer(config, { database, validateUser: async () => null, verifyAssets: async () => {} })).rejects.toThrow("Private staging dependencies are unavailable.")
    expect(closed).toBe(true)
    let contained = true
    database.checkReadiness = async () => ({ profile: STAGING_PROFILE, schemaVersion: 12, legacyContainmentVerified: contained })
    const app = await createStagingServer(config, { database, validateUser: async () => null, verifyAssets: async () => {}, log: () => {} })
    cleanup = app.close
    expect((await app.fetch(new Request(`${ORIGIN}/workspace-api/config`))).status).toBe(200)
    contained = false
    expect((await app.fetch(new Request(`${ORIGIN}/workspace-api/config`))).status).toBe(503)
    expect((await app.fetch(new Request(`${ORIGIN}/workspace-api/session`, { headers: { authorization: "Bearer any-token" } }))).status).toBe(503)
    expect((await app.fetch(new Request(`${ORIGIN}/ready`))).status).toBe(503)
  })

  test("session uses verified identity and current membership; public config contains only public fields", async () => {
    const f = await fixture()
    const config = await f.request("/workspace-api/config")
    expect(await config.json()).toEqual({ profile: STAGING_PROFILE, supabaseUrl: environment.SUPABASE_URL, anonKey: environment.SUPABASE_ANON_KEY })
    for (const token of [undefined, "m54-synthetic-owner", "expired-session"]) expect((await f.request("/workspace-api/session", token)).status).toBe(401)
    const session = await f.request("/workspace-api/session", "test-admin-session")
    expect(await session.json()).toEqual({ profile: STAGING_PROFILE, user: { id: ADMIN }, access: { role: "admin", workspaceId: f.workspace.id, evidenceId: null } })
    f.invited.delete(ADMIN)
    expect((await f.request("/workspace-api/session", "test-admin-session")).status).toBe(403)
    expect((await f.request(`/workspace-api/workspace/${f.workspace.id}`, "test-admin-session")).status).toBe(403)
  })

  test("same-origin wrapper reaches actual SQL routes, withholds foreign workspace and preserves multipart uploads", async () => {
    const f = await fixture()
    const own = await f.request(`/workspace-api/workspace/${f.workspace.id}`, "test-owner-session")
    expect(own.status).toBe(200)
    expect((await own.json()).id).toBe(f.workspace.id)
    const foreign = await f.request(`/workspace-api/workspace/${f.workspace.id}`, "test-outsider-session")
    const unknown = await f.request("/workspace-api/workspace/99999999-9999-4999-8999-999999999999", "test-outsider-session")
    expect(foreign.status).toBe(404)
    expect(await foreign.json()).toEqual(await unknown.json())
    const form = new FormData()
    form.append("file", new File([await Bun.file(new URL("../../../../output/pdf/neuvetra-m55-synthetic-electricity-bill.pdf", import.meta.url)).bytes()], "neuvetra-m55-synthetic-electricity-bill.pdf", { type: "application/pdf" }))
    const upload = await f.request(`/workspace-api/workspace/${f.workspace.id}/bills`, "test-owner-session", { method: "POST", body: form })
    expect(upload.status).toBe(200)
    const evidence = await upload.json()
    expect(evidence.companyId).toBe(f.workspace.id)
    f.evidence(evidence.id)
    expect((await (await f.request("/workspace-api/session", "test-admin-session")).json()).access.evidenceId).toBe(evidence.id)
    const mutation = await f.request(`/workspace-api/workspace/${f.workspace.id}/bills`, "test-member-session", { method: "POST", body: form })
    expect(mutation.status).toBe(403)
  })

  test("readiness fails closed and errors/logs contain no credentials, personal metadata or body", async () => {
    const f = await fixture()
    expect((await f.request("/ready")).status).toBe(200)
    f.unhealthy()
    const readiness = await f.request("/ready")
    expect(readiness.status).toBe(503)
    expect(await readiness.json()).toEqual({ status: "unavailable" })
    expect((await f.request("/health")).status).toBe(200)
    const failure = await f.request("/workspace-api/session", "broken-session")
    expect(failure.status).toBe(503)
    expect(await failure.text()).not.toContain("sensitive")
    const serialized = JSON.stringify(f.logs)
    for (const forbidden of ["broken-session", "private@example.invalid", "sensitive", environment.DATABASE_URL, OWNER]) expect(serialized).not.toContain(forbidden)
    expect(f.logs.every((entry) => Object.keys(entry).sort().join("|") === "durationMs|event|requestId|route|status")).toBe(true)
  })

  test("origin, size and path refusals cover actual dispatch; no-store applies to every response", async () => {
    const f = await fixture()
    expect((await f.request("/workspace-api/session", "test-owner-session", { headers: { origin: "https://foreign.invalid" } })).status).toBe(403)
    const tooLarge = await f.request("/workspace-api/workspace", "test-owner-session", { method: "POST", body: "x".repeat(300_001) })
    expect(tooLarge.status).toBe(413)
    for (const pathname of ["/", "/workspace-api/config", "/health", "/.env", "/workspace-api/no-such-route"]) {
      const response = await f.request(pathname, "test-owner-session")
      expect(response.headers.get("cache-control")).toBe("no-store")
      expect(response.headers.get("x-content-type-options")).toBe("nosniff")
      if (pathname === "/.env" || pathname.endsWith("no-such-route")) expect(response.status).toBe(404)
    }
  })

  test("static serving is confined to the approved web root and asset namespace", async () => {
    const root = await mkdtemp(path.join(tmpdir(), "neuvetra-m63-static-"))
    cleanup = async () => rm(root, { recursive: true, force: true })
    await mkdir(path.join(root, "assets"))
    await writeFile(path.join(root, "index.html"), "<html><body>Staging</body></html>")
    await writeFile(path.join(root, "assets", "app.js"), "export {}")
    await writeFile(path.join(root, ".env"), "private fixture")
    expect((await serveStagingAsset(root, "/"))?.status).toBe(200)
    expect((await serveStagingAsset(root, "/assets/app.js"))?.status).toBe(200)
    for (const target of ["/.env", "/assets/../.env", "/assets/%2e%2e/.env", "/output/report.html", "/assets/app.js.map"]) expect(await serveStagingAsset(root, target)).toBeNull()
    await verifyStagingAssets(root)
  })
})

import { createSourceWorksheetRoutes } from "../workspace/m66-routes"
import { createSourceWorksheetReportRoutes } from "../workspace/m66-report-routes"
import { createElectricitySourceRoutes } from "../workspace/m66-source-routes"
import { createWorksheetReportRoutes } from "../workspace/m65-routes"
import { createWorksheetRoutes } from "../workspace/m64-routes"
import { HostedWorkspaceDatabase, loadStagingDatabaseCa, type WorkspaceDatabase, type CompanyWorkspaceRecord } from "@neuvetra/database"
import { createClient } from "@supabase/supabase-js"
import { extractBearerToken, validateUserFromToken, type AuthenticatedUser } from "../lib/auth"
import { createRateLimiter } from "../lib/rate-limit"
import { createWorkspaceRoutes } from "../workspace/routes"
import { createWorkspaceStore } from "../workspace/service"
import { readStagingConfig, STAGING_PROFILE, type StagingConfig } from "./config"
import { serveStagingAsset, verifyStagingAssets } from "./assets"

const MAX_BODY_BYTES = 300_000
type Access = { workspace: CompanyWorkspaceRecord; role: "owner" | "admin" | "member"; evidenceId: string | null }
export type StagingDatabase = WorkspaceDatabase & {
  hasStagingAccess(userId: string): Promise<boolean>
  findStagingWorkspaceForUser(userId: string): Promise<Access | null>
  checkReadiness(): Promise<{ profile: string; schemaVersion: number; legacyContainmentVerified?: boolean }>
}

export interface StagingLog {
  event: "request"
  requestId: string
  route: "health" | "ready" | "config" | "session" | "workspace" | "asset" | "unknown"
  status: number
  durationMs: number
}

export interface StagingOverrides {
  database?: StagingDatabase
  validateUser?: (token: string) => Promise<AuthenticatedUser | null>
  verifyAssets?: () => Promise<void>
  serveAsset?: (pathname: string) => Promise<Response | null>
  log?: (event: StagingLog) => void
}

function json(status: number, value: unknown) { return Response.json(value, { status }) }

async function boundedRequest(request: Request, url: URL): Promise<Request> {
  const claimed = request.headers.get("content-length")
  if (claimed && (!/^\d+$/.test(claimed) || Number(claimed) > MAX_BODY_BYTES)) throw new Error("Request too large.")
  if (!request.body) return new Request(url, request)
  const reader = request.body.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      total += value.byteLength
      if (total > MAX_BODY_BYTES) { await reader.cancel(); throw new Error("Request too large.") }
      chunks.push(value)
    }
  } finally { reader.releaseLock() }
  const body = new Uint8Array(total)
  let position = 0
  for (const chunk of chunks) { body.set(chunk, position); position += chunk.byteLength }
  return new Request(url, { method: request.method, headers: request.headers, body, signal: request.signal })
}

/** No listener, migration or credential read occurs at import time. */
export async function createStagingServer(config: StagingConfig, overrides: StagingOverrides = {}) {
  if (config.profile !== STAGING_PROFILE) throw new Error("Private staging profile is invalid.")
  const database: StagingDatabase = overrides.database ?? await HostedWorkspaceDatabase.create({ connectionString: config.databaseUrl, expectedProjectRef: config.projectRef, reuseExistingProject: config.reuseExistingProject, tlsCaPem: await loadStagingDatabaseCa({ caPem: config.databaseCaPem, caFile: config.databaseCaFile }) })
  const auth = overrides.validateUser ?? (() => {
    const boundedFetch = ((input: RequestInfo | URL, init?: RequestInit) => fetch(input, { ...init, signal: AbortSignal.timeout(5_000) })) as typeof fetch
    const client = createClient(config.supabaseUrl, config.supabaseAnonKey, { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }, global: { fetch: boundedFetch } })
    return (token: string) => validateUserFromToken(token, client)
  })()
  const checkAssets = overrides.verifyAssets ?? (() => verifyStagingAssets(config.webRoot))
  const serveAsset = overrides.serveAsset ?? ((pathname: string) => serveStagingAsset(config.webRoot, pathname))
  const log = overrides.log ?? ((event: StagingLog) => console.info(JSON.stringify(event)))
  const admission = createRateLimiter({ max: 360, windowMs: 60_000, maxBuckets: 1 })
  const actors = createRateLimiter({ max: 120, windowMs: 60_000, maxBuckets: 100 })
  const validateUser = async (token: string) => {
    const user = await auth(token)
    return user && await database.hasStagingAccess(user.id) ? user : null
  }
  const routes = createWorkspaceRoutes({
    allowedOrigins: [config.origin], validateUser,
    store: createWorkspaceStore(database, async (userId) => {
      const access = await database.findStagingWorkspaceForUser(userId)
      if (!access || access.role !== "owner") throw new Error("Workspace not found.")
      return access.workspace
    }),
  })
  const sourceWorksheetRoutes=createSourceWorksheetRoutes({database,validateUser,origin:config.origin})
  const sourceReportRoutes=createSourceWorksheetReportRoutes({database,validateUser,origin:config.origin})
  const electricitySourceRoutes=createElectricitySourceRoutes({database,validateUser,origin:config.origin})
  const reportRoutes = createWorksheetReportRoutes({ database, validateUser, origin: config.origin })
  const worksheetRoutes = createWorksheetRoutes({ database, validateUser, origin: config.origin })
  const databaseReadiness = async () => {
    const receipt = await database.checkReadiness()
    if (receipt.profile !== STAGING_PROFILE || receipt.schemaVersion !== 12) throw new Error("Staging database unavailable.")
    if (config.projectRef === "icockcoguyadhryzydvl" && (!config.reuseExistingProject || receipt.legacyContainmentVerified !== true)) throw new Error("Existing project containment unavailable.")
    return receipt
  }
  const readiness = async () => { const receipt = await databaseReadiness(); await checkAssets(); return receipt }
  try { await readiness() } catch { await database.close(); throw new Error("Private staging dependencies are unavailable.") }

  const routeName = (pathname: string): StagingLog["route"] => pathname === "/health" ? "health" : pathname === "/ready" ? "ready" : pathname === "/workspace-api/config" ? "config" : pathname === "/workspace-api/session" ? "session" : pathname.startsWith("/workspace-api/workspace") ? "workspace" : pathname === "/" || pathname === "/workspace" || pathname.startsWith("/assets/") ? "asset" : "unknown"

  async function dispatch(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const isGet = request.method === "GET"
    if (url.pathname === "/health" && isGet) return json(200, { status: "alive" })
    if (url.pathname === "/ready" && isGet) {
      try { const receipt = await readiness(); return json(200, { status: "ready", ...receipt }) }
      catch { return json(503, { status: "unavailable" }) }
    }
    if (url.pathname.startsWith("/workspace-api/")) {
      const origin = request.headers.get("origin")
      if ((origin && origin !== config.origin) || (!isGet && origin !== config.origin)) return json(403, { error: "Forbidden." })
      if (!admission.check("staging").allowed) return json(429, { error: "Request limit reached." })
      if (config.projectRef === "icockcoguyadhryzydvl") await databaseReadiness()
      if (url.pathname === "/workspace-api/config" && isGet) return json(200, { profile: STAGING_PROFILE, supabaseUrl: config.supabaseUrl, anonKey: config.supabaseAnonKey })
      const token = extractBearerToken(request.headers)
      if (!token || token.length > 8192) return json(401, { error: "Authentication required." })
      let user: AuthenticatedUser | null
      try { user = await auth(token) } catch { return json(503, { error: "Authentication is unavailable." }) }
      if (!user) return json(401, { error: "Authentication required." })
      if (!actors.check(user.id).allowed) return json(429, { error: "Request limit reached." })
      if (!await database.hasStagingAccess(user.id)) return json(403, { error: "Private staging access required." })
      if (url.pathname === "/workspace-api/session" && isGet) {
        const access = await database.findStagingWorkspaceForUser(user.id)
        if (!access) return json(403, { error: "Private staging access required." })
        return json(200, { profile: STAGING_PROFILE, user: { id: user.id }, access: { role: access.role, workspaceId: access.workspace.id, evidenceId: access.evidenceId } })
      }
      url.pathname = url.pathname.slice("/workspace-api".length)
      let forwarded: Request
      try { forwarded = await boundedRequest(request, url) } catch { return json(413, { error: "Request too large." }) }
      if (url.pathname.includes("/source-electricity-worksheet/sources")) return electricitySourceRoutes(forwarded)
      if (url.pathname.includes("/source-electricity-worksheet/reports")) return sourceReportRoutes(forwarded)
      if (url.pathname.includes("/source-electricity-worksheet")) return sourceWorksheetRoutes(forwarded)
      if (url.pathname.includes("/electricity-worksheet/reports")) return reportRoutes(forwarded)
      if (url.pathname.includes("/electricity-worksheet")) return worksheetRoutes(forwarded)
      return routes.handle(forwarded)
    }
    if (isGet) return await serveAsset(url.pathname) ?? json(404, { error: "Not found." })
    return json(404, { error: "Not found." })
  }

  return {
    async fetch(request: Request) {
      const started = performance.now()
      const requestId = crypto.randomUUID()
      let response: Response
      try { response = await dispatch(request) } catch { response = json(503, { error: "Private staging is unavailable." }) }
      const headers = new Headers(response.headers)
      headers.set("cache-control", "no-store")
      headers.set("x-request-id", requestId)
      headers.set("x-content-type-options", "nosniff")
      headers.set("referrer-policy", "no-referrer")
      headers.set("x-frame-options", "DENY")
      if (!headers.has("content-security-policy")) headers.set("content-security-policy", `default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self' ${config.supabaseUrl}; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'; form-action 'self'; object-src 'none'`)
      if (config.origin.startsWith("https:")) headers.set("strict-transport-security", "max-age=31536000")
      try { log({ event: "request", requestId, route: routeName(new URL(request.url).pathname), status: response.status, durationMs: Math.round(performance.now() - started) }) } catch { /* Log failures cannot disclose request contents or turn a committed write into a client failure. */ }
      return new Response(response.body, { status: response.status, headers })
    },
    close: () => database.close(),
  }
}

if (import.meta.main) {
  try {
    const config = readStagingConfig()
    const app = await createStagingServer(config)
    const server = Bun.serve({ hostname: "0.0.0.0", port: config.port, maxRequestBodySize: MAX_BODY_BYTES, idleTimeout: 30, fetch: app.fetch })
    const shutdown = async () => { await server.stop(); await app.close(); process.exit(0) }
    process.once("SIGINT", shutdown)
    process.once("SIGTERM", shutdown)
    console.info(JSON.stringify({ event: "staging_started", profile: STAGING_PROFILE }))
  } catch {
    console.error(JSON.stringify({ event: "staging_start_failed" }))
    process.exitCode = 1
  }
}

import { expect, test } from "bun:test"
import { createPostgresConnection, HostedWorkspaceDatabase, provisionStagingRoster, revokeStagingAccess, M66_LIMITATIONS, readSourceWorksheetReports, type WorkspaceConnection } from "@neuvetra/database"
import { M66_SOURCE_FIXTURES } from "../../../../packages/neuvetra-database/src/m66-fixtures"
import { createStagingServer } from "../staging/server"
import { readStagingConfig, STAGING_PROFILE } from "../staging/config"
const target=process.env.M66_API_TEST_DATABASE_URL??process.env.M63_API_TEST_DATABASE_URL
if(target){const u=new URL(target);if(u.hostname!=="127.0.0.1"||u.port!=="55463"||!["/m66_author","/m63_integration"].includes(u.pathname)||u.username!=="m63_test_admin"||u.password||u.search||u.hash)throw new Error("M66 native tests require an explicitly approved loopback fixture.")}
const integration=target?test:test.skip
integration("M66 actual driver and staged API preserve source-to-report lineage, exact arithmetic, conflicts and prior records",async()=>{
 const REF="abcdefghijklmnopqrst",ORIGIN="http://127.0.0.1:3015",company=crypto.randomUUID()
 const users={owner:crypto.randomUUID(),admin:crypto.randomUUID(),manager:crypto.randomUUID(),member:crypto.randomUUID(),outsider:crypto.randomUUID()}
